package com.heirteir.autoeye.check.checks.movement;

import com.heirteir.autoeye.Autoeye;
import com.heirteir.autoeye.check.Check;
import com.heirteir.autoeye.check.CheckType;
import com.heirteir.autoeye.player.AutoEyePlayer;

public class InventoryWalk extends Check {
    public InventoryWalk(Autoeye autoeye) {
        super(autoeye, CheckType.INVENTORY_EVENT, "Inventory Walk");
    }

    @Override public boolean check(AutoEyePlayer player) {
        return player.getLocationData().isChangedPos() && player.getTimeData().getLastFlying().getAmount() == 0 && player.getPhysics().isMoving() && player.getPhysics().getServerVelocity().getX() == 0 && player.getPhysics().getServerVelocity().getZ() == 0 && player.getTimeData().getLastMove().getDifference() < 60L;
    }

    @Override public boolean revert(AutoEyePlayer player) {
        player.getPlayer().closeInventory();
        return false;
    }
}

// NOTE (AI): AutoEye uses a revert model: the check undoes the cheat action by closing the inventory instead of cancelling the packet.
